create extension if not exists pgcrypto;
create table public.people(id text primary key,kind text not null check(kind in('host','team')),name text not null,category text,role text,color text not null default '#3566d6',photo_url text,include_in_compare boolean not null default true,sort_order int not null default 0);
create table public.calendar_boards(id text primary key,kind text not null check(kind in('host','team','compare')),title text not null,updated_at timestamptz not null default now());
create table public.calendar_events(id uuid primary key default gen_random_uuid(),person_id text not null references public.people(id) on delete cascade,event_date date not null,label text not null default '',show_label boolean not null default true,kind text not null check(kind in('host','team')),board_id text not null,updated_at timestamptz not null default now());
create table public.day_notes(id uuid primary key default gen_random_uuid(),board_id text not null,note_date date not null,note text not null default '',show_note boolean not null default true,updated_at timestamptz not null default now(),unique(board_id,note_date));
create table public.host_availability(person_id text not null references public.people(id) on delete cascade,available_date date not null,primary key(person_id,available_date));
create table public.host_assignments(person_id text not null references public.people(id) on delete cascade,assignment_date date not null,primary key(person_id,assignment_date));
alter table public.people enable row level security;alter table public.calendar_boards enable row level security;alter table public.calendar_events enable row level security;alter table public.day_notes enable row level security;alter table public.host_availability enable row level security;alter table public.host_assignments enable row level security;
grant select,insert,update,delete on public.people,public.calendar_boards,public.calendar_events,public.day_notes,public.host_availability,public.host_assignments to anon;
create policy "link all people" on public.people for all to anon using(true) with check(true);create policy "link all boards" on public.calendar_boards for all to anon using(true) with check(true);create policy "link all events" on public.calendar_events for all to anon using(true) with check(true);create policy "link all day notes" on public.day_notes for all to anon using(true) with check(true);create policy "link all availability" on public.host_availability for all to anon using(true) with check(true);create policy "link all assignments" on public.host_assignments for all to anon using(true) with check(true);
insert into public.calendar_boards values('host-main','host','ปฏิทินพิธีกรข่าวแหกโค้ง',now()),('team-main','team','ตารางเวรทีมข่าวแหกโค้ง',now()),('compare-main','compare','ตารางเทียบคิวพิธีกรข่าวแหกโค้ง',now());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('people-photos','people-photos',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy "link view photos" on storage.objects for select to anon using(bucket_id='people-photos');create policy "link upload photos" on storage.objects for insert to anon with check(bucket_id='people-photos');create policy "link update photos" on storage.objects for update to anon using(bucket_id='people-photos') with check(bucket_id='people-photos');
alter publication supabase_realtime add table public.people,public.calendar_boards,public.calendar_events,public.day_notes,public.host_availability,public.host_assignments;
